    Bug 2046137 - Add a slightly tighter bound when searching for whitespace in MIME headers. r=kaie

    Differential Revision: https://phabricator.services.mozilla.com/D309169

diff --git a/mailnews/mime/src/mimedrft.cpp b/mailnews/mime/src/mimedrft.cpp
index ebebe3f1c60..6ecb3b78c5c 100644
--- a/mailnews/mime/src/mimedrft.cpp
+++ b/mailnews/mime/src/mimedrft.cpp
@@ -649,7 +649,7 @@ static void mime_insert_all_headers(char** body, MimeHeaders* headers,
     }

     /* Skip over whitespace after colon. */
-    while (contents <= end && IS_SPACE(*contents)) contents++;
+    while (contents < end && IS_SPACE(*contents)) contents++;

     /* Take off trailing whitespace... */
     while (end > contents && IS_SPACE(end[-1])) end--;
